{
  "tasks": [
    {
      "task_id": "T1",
      "title": "各团队平均响应分钟比较",
      "business_question": "按团队分组，计算并比较各团队的平均响应分钟是多少？",
      "priority": "P0",
      "priority_reason": "核心需求为“按团队比较平均响应分钟”，删除此任务将无法回答业务目标。响应分钟字段(field_0005)为数值类型，支持avg聚合；团队字段(field_0002)为文本维度，支持group_aggregate。无明确时间或状态筛选约束，因此对全量数据进行分组统计。",
      "requirement_ids": [
        "C01",
        "C02"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "avg",
                "field": "field_0005",
                "alias": "avg_response_minutes"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        },
        {
          "step_id": "S2",
          "operation": "sort",
          "params": {
            "field": "avg_response_minutes",
            "direction": "asc"
          }
        }
      ]
    }
  ]
}
